In draw_text, resolve each decoration's style once and sweep. Cell positions only move forward through a window, so the sweep restarts if one ever goes back:
```rust
// Each decoration's style once; `deco`'s order is the stacking order.
let layers: Vec<(Range<usize>, Style)> =
    deco.iter().map(|(r, f)| (r.clone(), faces.get(f))).collect();
let mut by_start: Vec<usize> = (0..layers.len()).collect();
by_start.sort_by_key(|&i| layers[i].0.start);
let (mut next, mut active, mut m, mut prev) = (0, Vec::<usize>::new(), 0, 0);
let mut style_at = |q: usize| {
    if q < prev { (next, m) = (0, 0); active.clear(); }
    prev = q;
    while next < by_start.len() && layers[by_start[next]].0.start <= q {
        let i = by_start[next];
        active.insert(active.partition_point(|&a| a < i), i);
        next += 1;
    }
    active.retain(|&i| layers[i].0.end > q);
    let mut s = active.iter().fold(base, |s, &i| layers[i].1.over(s));
    while m < hl.search.len() && hl.search[m].end <= q { m += 1; }
    let current = hl.current.as_ref().is_some_and(|r| r.contains(&q));
    if current || hl.search.get(m).is_some_and(|r| r.contains(&q)) { /* as today */ }
    // bracket and selection as today, but compute a linewise selection's byte
    // range once (line start of the first line .. line start after the last)
    s
};
```
