Add to xtask/src/lint.rs, and call it from run() for every file, next to check_unsafe_allows:
```rust
/// Where the `unsafe` keyword may appear (scope §12). M2 adds die-core's `sys/`
/// and die-term's engine boundary; `platform/linux/` joins with its code.
const UNSAFE_DIRS: &[&str] = &["crates/die-render/src/platform/macos/"];

/// The `unsafe` keyword in any form outside `UNSAFE_DIRS`: a block, an `unsafe`
/// fn, impl, trait or extern block, and unsafe attributes such as
/// `#[unsafe(naked)]`, which rustc's `unsafe_code` lint misses. Reading the
/// keyword also catches a lint level a macro builds (`#[allow($lint)]`).
/// `#[path = …]` and `include!` are flagged everywhere: they compile a file
/// this scan may never read.
pub fn check_unsafe_tokens(rel: &str, src: &str, errors: &mut Vec<String>) {
    use crate::count::{Tok, lex};
    let toks = lex(src);
    let is = |i: usize, t: Tok| toks.get(i).map(|x| &x.0) == Some(&t);
    let unsafe_ok = UNSAFE_DIRS.iter().any(|d| rel.starts_with(d));
    for (i, (tok, line, _)) in toks.iter().enumerate() {
        let Tok::Ident(w) = tok else { continue };
        let what = match w.as_str() {
            "unsafe" if !unsafe_ok => format!("`unsafe` outside {}", UNSAFE_DIRS.join(", ")),
            "include" if is(i + 1, Tok::Punct('!')) => "`include!` (it compiles a file the lint may not read)".into(),
            "path" if i > 0 && is(i - 1, Tok::Punct('[')) && is(i + 1, Tok::Punct('=')) => "`#[path]` (it compiles a file the lint may not read)".into(),
            _ => continue,
        };
        errors.push(format!("{rel}:{}: {what} (scope §12)", line + 1));
    }
}
```
